def generate_icons():
    for name, svg in SVGS.items():
        filepath = os.path.join(ICONS_DIR, f"{name}.svg")
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(svg)
    print(f"Generated {len(SVGS)} SVG icons in {ICONS_DIR}")

if __name__ == "__main__":
    generate_icons()
